import type { ContentCatalogue } from '../content'

export const ES_REGISTERBACKGROUND: ContentCatalogue = {
  "regbg.ancients.h": { fp: "puxvwx", text: "Los críticos antiguos ya tenían nombres para esto" },
  "regbg.ancients.p0": { fp: "1m20o9m", text: "La distinción que la herramienta mide como PERIODICIDAD es de Aristóteles. En Retórica 3.9 separa la λέξις εἰρομένη —el estilo «ensartado», cuyas oraciones simplemente se van añadiendo una tras otra y que, dice, no tiene fin en sí mismo sino que se detiene cuando se acaba el asunto— de la λέξις κατεστραμμένη, el estilo periódico, cuyas oraciones se pliegan en un todo que puede abarcarse de una vez con la mente. A él le parecía arcaico el primero y un progreso el segundo. Se piense lo que se piense de ese juicio, la distinción es real y contable: es la diferencia entre unir oraciones con καί e incrustarlas como participios, infinitivos y oraciones con ὅτι." },
  "regbg.ancients.p1": { fp: "z7l7jq", text: "Los críticos posteriores multiplicaron las categorías. Demetrio (Sobre el estilo) maneja cuatro χαρακτῆρες: llano, grandioso, elegante y vehemente. Dionisio de Halicarnaso (Sobre la composición literaria) da tres ἁρμονίαι: austera, pulida y una mezcla de ambas. Los tres genera dicendi de la retórica latina —sublime, medio y llano— son el mismo instinto en otra lengua. Ninguna de estas es una taxonomía que una computadora pueda aplicar, porque cada una depende de juicios sobre el sonido y el efecto. La de Aristóteles es la excepción, y por eso es la que aquí está implementada." },
  "regbg.ancients.p2": { fp: "ym7ehv", text: "Dos etiquetas antiguas más importan para el otro eje. El ATICISMO fue el movimiento que, a partir del siglo I a. C., sostuvo que la prosa ática del siglo IV era el único griego correcto y se propuso volver a escribirlo. ASIANISMO era como sus partidarios llamaban al estilo contemporáneo recargado contra el que reaccionaban. Un autor imperial que escribe en ático está tomando una decisión sobre el registro, no exhibiendo una fecha, y precisamente por eso esta herramienta etiqueta su segundo eje por dirección y no por periodo." },
  "regbg.axes.h": { fp: "ehm99", text: "Qué hacen realmente los dos ejes" },
  "regbg.axes.p0": { fp: "32ybc1", text: "La PERIODICIDAD es la proporción del enlace entre oraciones que se hace por subordinación y no por coordinación: participios, infinitivos, ὅτι e ἵνα frente a καί y δέ. Es una proporción, así que la longitud no entra en ella. La objeción evidente es que καί coordina sustantivos además de oraciones y por tanto se cuenta de más; es cierto, y desplaza todos los textos en la misma dirección, dejando intacto el orden, que es para lo que se lee esto." },
  "regbg.axes.p1": { fp: "k686dr", text: "La INCLINACIÓN CLÁSICA sitúa un texto en la línea que va del perfil clásico medio al perfil koiné medio, proyectando su perfil de frecuencias de palabras sobre el eje que une esos dos centros. +1 es el promedio clásico y −1 el koiné; un texto puede quedar fuera de ambos. Medir la distancia a cada centro por separado se probó primero y no sirve: en 150 dimensiones todo está lejos de cualquier promedio, y Luciano y Génesis salían indistinguibles." },
  "regbg.axes.p2": { fp: "14iqbhv", text: "No se llama aticismo, y dos resultados son la razón. El conjunto clásico de esta biblioteca son 123 discursos forenses frente a dos historias, así que el eje mide en realidad la distancia respecto de la ORATORIA ática: Tucídides, idiosincrásico para cualquier medida, puntúa bastante por debajo de Platón. Y discrepa de la periodicidad. Hebreos y 1 Pedro son los libros más periódicos del Nuevo Testamento y sin embargo se inclinan más lejos del ático que Juan, porque construyen sus frases con elaboración a partir de vocabulario septuagintal. Un texto puede estar retóricamente trabajado con palabras enteramente koiné, y una etiqueta que dijera «aticismo» habría escondido eso tras una afirmación que la cifra no puede sostener." },
  "regbg.axes.p3": { fp: "d1n1p9", text: "Ninguno de los dos ejes resuelve nada sobre autoría, fecha o dependencia. Son descripciones de cómo está construido un texto, ofrecidas en el vocabulario que el debate ha usado siempre, para que una impresión —«Hebreos es más literario que Marcos»— pueda contrastarse con algo contable, y para que los lugares donde la cuenta discrepa de la impresión se vuelvan visibles en vez de quedar ocultos." },
  "regbg.koine.h": { fp: "1nrtoy6", text: "La descripción moderna del koiné" },
  "regbg.koine.p0": { fp: "1o8fj4m", text: "La lingüística histórica describe el griego posclásico como una gama y no como una sola cosa, que suele ir desde un extremo literario aticista (Luciano, Filóstrato, Dión Crisóstomo), pasando por el koiné literario (Polibio, Estrabón, Plutarco, Josefo, Filón), hasta el griego documental de los papiros y, por debajo, una escritura simplemente subestándar. Greek: A History of the Language and its Speakers, de Geoffrey Horrocks, es la referencia habitual para todo el arco." },
  "regbg.koine.p1": { fp: "xv819u", text: "La Septuaginta se trata como un caso aparte, porque es traducción. Una literatura considerable sobre la «técnica de traducción» —Tov, Aejmelaeus, Sollamo y otros— se pregunta hasta qué punto cada traductor siguió el hebreo oración por oración, y la respuesta varía de libro en libro. Esa variación se ve en esta herramienta: Génesis es el texto más paratáctico de la biblioteca, que es lo que produce verter la narración hebrea oración por oración." },
  "regbg.koine.p2": { fp: "d3v2rr", text: "La imitación de ese griego traducido se llama SEPTUAGINTISMO, y es una decisión de registro tomada por escritores perfectamente capaces de escribir de otro modo. Lucas es el ejemplo canónico, y es lo más claro que esta herramienta muestra: compara Lucas 1-2 con Lucas 3-24 y la narración de la infancia queda junto a 1 Reyes, Judit y Tobías, mientras que el resto del Evangelio queda junto a Mateo, Marcos y Hechos." },
  "regbg.lede": { fp: "i9phpq", text: "El registro —el nivel y la textura de la lengua de un texto— se ha descrito para el griego en tres tradiciones que rara vez se citan entre sí: los críticos antiguos que escribían sobre su propia lengua, la lingüística histórica moderna del koiné y la teoría del registro propiamente dicha, tal como llegó a los estudios bíblicos desde Halliday. Esta herramienta mide cosas que a las tres les importan. Lo que sigue explica de dónde vienen sus dos ejes con nombre y qué es lo que no resuelven." },
  "regbg.nt.h": { fp: "16s8sbl", text: "El Nuevo Testamento en esa escala" },
  "regbg.nt.p0": { fp: "1563pq0", text: "Desde Blass es habitual ordenar los libros del Nuevo Testamento en un continuo literario: Hebreos y Lucas-Hechos en el extremo literario —siendo el prólogo de Lucas, 1:1-4, la frase más clasicista de toda la colección—, con Santiago y 1 Pedro arriba, Pablo en el medio, y Marcos, Juan y Apocalipsis en el extremo más llano o más semitizado. La herramienta reproduce ese orden en la periodicidad sin que se lo hayan dicho: Apocalipsis el más bajo, luego Marcos, luego Mateo y Lucas, con Hechos por encima del Evangelio de Lucas, y Hebreos y 1 Pedro en lo alto." },
  "regbg.nt.p1": { fp: "1k157du", text: "SEMITISMO es la etiqueta habitual para los rasgos atribuidos a influencia hebrea o aramea, subdividida en hebraísmo y arameísmo, y además en interferencia (un bilingüe que escribe griego) y traducción (un texto vertido de un original semítico). Las categorías son útiles; la atribución de cualquier rasgo concreto a una de ellas suele ser discutible." },
  "regbg.nt.p2": { fp: "1gyt4wd", text: "Hay una postura antigua hoy en buena medida abandonada que conviene conocer, porque la literatura secundaria está llena de ella. Durante todo el siglo XIX el griego bíblico se trató a menudo como un dialecto aparte, una lengua especial de la Escritura, célebremente descartada como «el griego del Espíritu Santo». El trabajo de Adolf Deissmann sobre los papiros a partir de la década de 1890 mostró que buena parte de lo que se creía peculiar del Nuevo Testamento era corriente en el griego documental de la época. La formulación más fuerte de la vieja postura en el siglo XX fue la de Nigel Turner, en el cuarto volumen de la gramática de Moulton; no ha convencido a la mayor parte de la investigación posterior. Lo que sobrevive es el «registro semitizante» —una manera de escribir— y no el «griego judío», una lengua aparte." },
  "regbg.register-theory.h": { fp: "11w2lcp", text: "El registro en sentido técnico" },
  "regbg.register-theory.p0": { fp: "19fav6a", text: "La palabra «registro» como término técnico viene de M. A. K. Halliday, para quien es la configuración de la lengua que una situación suscita, analizada como campo (qué está ocurriendo), tenor (quiénes intervienen y qué relación guardan) y modo (el papel que desempeña la lengua). Entró en los estudios neotestamentarios sobre todo por Stanley Porter y por trabajos de análisis del discurso como el de Jeffrey Reed sobre Filipenses." },
  "regbg.register-theory.p1": { fp: "1cngo7p", text: "Según esa definición, el registro es una propiedad de la SITUACIÓN, y lo que un texto exhibe son sus realizaciones lingüísticas. Esta herramienta mide las realizaciones. No puede ver la situación, y no debe leerse como si pudiera: dos textos que puntúan parecido aquí han mostrado compartir hábitos de construcción, lo cual es evidencia sobre el registro y no una descripción de él." },
}
